sys_script_fix.script:
setBOMATypeToNone();

function setBOMATypeToNone() {
    WPLogger.info('setBOMATypeToNone', 'Starting upgrade fix script to set BOMA type to None');

    var spaceTypeGr = new GlideRecord(WPConstants.TABLES.SPACE_TYPE);
    spaceTypeGr.addNullQuery('boma_type');
    spaceTypeGr.query();

    if (spaceTypeGr.hasNext()) {
        var noneBOMATypeGr = new GlideRecord(WPConstants.TABLES.BOMA_TYPE);
        noneBOMATypeGr.addQuery('name', 'None');
        noneBOMATypeGr.query();

        if (noneBOMATypeGr.next()) {
            var noneBOMATypeRecordSysId = noneBOMATypeGr.getUniqueValue();
            spaceTypeGr.setValue('boma_type', noneBOMATypeRecordSysId);
            spaceTypeGr.updateMultiple();
        }
    }

    WPLogger.info('setBOMATypeToNone', 'Finishing upgrade fix script to set BOMA type to None');
}
